import{t as e}from"./jsx-runtime-lw2jiZar.js";import{A as t,C as n,E as r,H as i,M as a,N as o,O as s,P as c,R as l,S as u,V as d,_ as f,a as p,k as m,l as h,o as g,p as _,t as v,x as y}from"./shared-CsAEn-Fy.js";import{t as b}from"./CodeEditor-BZlrvoTL.js";var x=e();function S({module:e}){return(0,x.jsxs)(o,{children:[(0,x.jsx)(a,{chip:e??`Блок 7 · Python Deeper`,title:`35. Выбор формы и базовая композиция`,intro:`Подготовленная Task не означает, что весь Planner нужно превращать в набор классов. Разберём, когда достаточно словаря или функции, что класс получает от композиции и почему сотрудничество объектов не требует наследования.`,tags:[{icon:(0,x.jsx)(i,{size:14}),label:`выбор формы`},{icon:(0,x.jsx)(d,{size:14}),label:`сотрудничество объектов`},{icon:(0,x.jsx)(l,{size:14}),label:`связи объектов`}]}),(0,x.jsxs)(c,{number:`00`,title:`От подготовленной модели к выбору ответственности`,children:[(0,x.jsx)(s,{children:`Мы подготовили Task и проверили, как она превращается в запись. Теперь решим, когда объект действительно помогает и как одна часть программы может поручить действие другой.`}),(0,x.jsx)(m,{variant:`connected`,items:[{title:`Точка старта`,description:`В app.models подготовлена одна Task с полями и преобразованиями; рабочие операции и хранение пока используют словари.`},{title:`Новый вопрос`,description:`Как выбрать форму нового компонента и связать объекты, не приписывая им чужие обязанности?`},{title:`Результат`,description:`Мы различим словарь, функцию, класс и dataclass, проследим композицию и распределим роли частей Planner.`}]}),(0,x.jsx)(`p`,{children:`Подготовка модели не переключила CLI или JSON на объекты. Это полезная граница: мы можем рассматривать архитектурные решения отдельно от миграции. Сначала разберём критерии выбора, затем проследим один небольшой пример сотрудничества, а в конце вернёмся к знакомым обязанностям Planner.`})]}),(0,x.jsxs)(c,{number:`01`,title:`Выбираем форму по задаче, а не по престижу`,children:[(0,x.jsx)(s,{children:`У нас уже есть несколько способов представить работу программы. У каждого своя роль: словарь удобно передаёт данные, функция выполняет действие, класс связывает состояние одного объекта с его поведением, а dataclass сокращает повторяющийся код модели. Более новый синтаксис сам по себе не делает решение лучше.`}),(0,x.jsx)(`p`,{children:`Например, запись задачи в словаре прямо показывает значения, которые можно сохранить или передать дальше. Функция вроде проверки названия получает вход и возвращает результат; ей обычно не нужно помнить отдельное состояние между вызовами. Task, напротив, представляет одну задачу: её поля относятся к конкретному экземпляру, а методы меняют или описывают именно его. Dataclass уместен, когда такая модель состоит из объявленных полей и мы хотим убрать шаблон создания и сравнения. Он не выполняет за нас проверку правил и не открывает JSON.`}),(0,x.jsx)(`p`,{children:`Сравним формы по тому, что они несут в знакомом Planner:`}),(0,x.jsx)(t,{rows:[[`dict`,`Явная запись значений задачи; подходит для текущей границы JSON.`],[`function`,`Отдельное действие над переданными данными, например нормализация названия.`],[`обычный class`,`Состояние одного объекта и методы, работающие с ним.`],[`dataclass`,`Модель с полями и сгенерированным шаблонным поведением; предметные правила остаются явными.`]]}),(0,x.jsx)(`p`,{children:`Перед выбором формы мы можем пройти три вопроса. Если нужно лишь преобразовать вход, начнём с функции. Если нужно передать или сохранить набор значений, словарь часто остаётся ясной записью. Если у отдельной сущности есть своё состояние и действия, которые это состояние читают или меняют, рассмотрим класс. Когда структура модели уже понятна и ручной код повторяет стандартную работу с полями, dataclass может убрать этот повтор. Ответ зависит от требуемой ответственности, а не от размера файла или желания «использовать ООП».`}),(0,x.jsx)(`p`,{children:`Можно представить функцию как краткий рецепт: мы передаём ингредиенты, получаем результат и не обязаны сохранять рядом отдельное состояние каждого запуска. Экземпляр Task больше похож на личную рабочую карточку: поля принадлежат одной задаче, а связанные действия обращаются к этой карточке. Граница аналогии важна: функция всё ещё может изменить переданный объект, а карточка не объясняет устройство Python. Сравнение помогает спросить, требуется ли компоненту собственное состояние и действия, а не назначить форму по внешнему сходству.`}),(0,x.jsx)(`p`,{children:`Проверим этот критерий на небольшом решении. Нормализация одной строки не хранит пользовательские настройки, историю вызовов или независимое состояние. Отдельный класс вокруг неё добавил бы объект, который нечего моделировать.`}),(0,x.jsx)(u,{statement:(0,x.jsxs)(x.Fragment,{children:[`Для `,(0,x.jsx)(`code`,{children:`normalize_title`}),`, которая только очищает переданную строку, отдельный класс обязателен, потому что в Planner уже есть класс Task.`]}),isTrue:!1,explanation:`Мы выбираем форму отдельно для каждой ответственности. Одна функция здесь проще: ей не требуется собственное состояние.`})]}),(0,x.jsxs)(c,{number:`02`,title:`Композиция связывает объекты через вызов`,children:[(0,x.jsx)(s,{children:`Композиция означает, что один объект использует другой для части своей работы. Потребитель хранит ссылку на зависимость и вызывает её известный метод. Зависимость выполняет свою часть и возвращает результат; роли остаются разделёнными.`}),(0,x.jsx)(`p`,{children:`Похожую связь можно увидеть у объекта представления и форматтера: первый знает, какие данные показать, второй превращает их в строку. Представление вызывает нужное действие и получает готовый текст, не выполняя форматирование самостоятельно.`}),(0,x.jsx)(`p`,{children:`Рассмотрим схему как путь одного запроса и ответа. Слева находится объект, который готовит напоминание, справа его канал доставки. Потребитель вызывает действие канала, а канал возвращает строку для наблюдения в нашем небольшом примере. Вызов и ответ идут в разные стороны, поэтому на схеме показаны две отдельные связи.`}),(0,x.jsx)(v,{caption:`Потребитель поручает доставку переданному объекту`,children:(0,x.jsxs)(g,{label:`Путь от напоминания к каналу и ответ обратно`,children:[(0,x.jsx)(h,{title:`Reminder`,shape:`process`,children:(0,x.jsx)(`p`,{children:`Готовит текст и вызывает deliver`})}),(0,x.jsx)(p,{forward:`вызывает deliver(text)`,reverse:`получает строку`}),(0,x.jsx)(h,{title:`Channel`,shape:`process`,children:(0,x.jsx)(`p`,{children:`Выполняет доставку выбранным способом`})})]})}),(0,x.jsx)(`p`,{children:`В этой аналогии Reminder похож на ведущего, который передаёт сообщение сменному исполнителю: ведущий задаёт, что нужно сделать, а исполнитель выбирает способ. Замена исполнителя не переписывает ведущего, если новый вариант умеет выполнить ожидаемое действие. Аналогия ограничена распределением ролей: реальная отправка сообщения может иметь сетевые ошибки и побочные эффекты, а следующий код только вернёт строку.`}),(0,x.jsx)(b,{caption:`Одна обязанность потребителя и два совместимых канала`,code:`class ScreenChannel:
    def deliver(self, message):
        return f"Экран: {message}"

class ArchiveChannel:
    def deliver(self, message):
        return f"Архив: {message}"

class Reminder:
    def __init__(self, channel):
        self.channel = channel

    def preview(self, message):
        return self.channel.deliver(message)

reminder = Reminder(ScreenChannel())
print(reminder.preview("Перерыв"))
reminder.channel = ArchiveChannel()
print(reminder.preview("Перерыв"))`}),(0,x.jsx)(`p`,{children:`При создании Reminder получает готовый объект Channel. Метод preview не знает внутреннее устройство канала: ему достаточно вызвать deliver с текстом. Сначала мы получим «Экран: Перерыв», затем заменим ссылку и получим «Архив: Перерыв». Объект Reminder остался тем же; изменился объект, которому он поручает доставку.`}),(0,x.jsx)(`p`,{children:`В примере объект получает ссылку извне, поэтому выбор канала виден при сборке Reminder. В другом варианте потребитель мог бы создать зависимость сам, но тогда его создание и выбор способа оказались бы теснее связаны. Для знакомства важно увидеть, что композиция описывает сотрудничество объектов, а не обязательное владение их временем жизни. Код не подключён к сети и не отправляет сообщения: оба канала только возвращают разные строки. В практике тот же вопрос появится у объекта представления и отдельного форматирования, но это будет самостоятельный пример, не новый слой Planner.`}),(0,x.jsx)(f,{code:`reminder.channel = ArchiveChannel()
print(reminder.preview("Перерыв"))`,output:`Архив: Перерыв`,hint:`Мы прослеживаем ссылку reminder.channel до её метода deliver.`})]}),(0,x.jsxs)(c,{number:`03`,title:`Заменяемая зависимость должна выполнять нужное действие`,children:[(0,x.jsx)(s,{children:`Чтобы замена сработала, потребитель и зависимость должны договориться о доступном поведении. В примере это имя deliver и аргумент с текстом. Два канала могут быть устроены по-разному; Reminder не требует от них общей родословной, но ожидает именно этот вызов.`}),(0,x.jsx)(`p`,{children:`Это небольшой договор использования, а не формальный интерфейс Python. Мы не объявляли базовый класс, протокол или правило, проверяющее все варианты заранее. Если вместо deliver в одном объекте есть только write, ошибка проявится при вызове потребителя. Поэтому совместимость означает наличие именно нужной операции с подходящим смыслом, а не одинаковые поля или одинаковую реализацию.`}),(0,x.jsx)(`p`,{children:`Рассмотрим намеренно неверную строку. Прежде чем выбрать причину, сопоставим, какое имя вызывает Reminder и какое действие реально доступно его каналу:`}),(0,x.jsx)(n,{code:`class ScreenChannel:
    def deliver(self, message):
        return f"Экран: {message}"

class Reminder:
    def __init__(self, channel):
        self.channel = channel

    def preview(self, message):
        return self.channel.format(message)`,question:`Какое несоответствие помешает выполнить preview?`,options:[`Reminder вызывает format, а канал предоставляет deliver`,`Reminder хранит ссылку в атрибуте экземпляра`,`deliver возвращает строку вместо нового объекта`],correctIndex:0,explanation:`Мы нашли несовпадение договора: вызов потребителя должен совпадать с действующим методом зависимости.`,fix:`return self.channel.deliver(message)`}),(0,x.jsx)(`p`,{children:`В программе Python не требует, чтобы классы были родственниками. Если оба переданных объекта поддерживают нужное действие, потребитель может работать с ними одним способом. Однако совпадение имени само по себе не гарантирует одинаковый смысл: мы проверяем также, что аргумент и результат подходят работе потребителя. Формальные интерфейсы и статическую проверку типов здесь не вводим.`}),(0,x.jsx)(`p`,{children:`На этом уровне соглашение существует между двумя участниками: потребитель знает нужный метод, а зависимость предоставляет его с ожидаемым результатом. Python не проверяет такую договорённость при передаче ссылки. Поэтому замена может обнаружить ошибку только в момент вызова, как в примере с format и deliver. Чем яснее мы называем действие и его результат, тем проще оценить, подходит ли новый вариант. Для этой темы достаточно проследить один вызов; отдельные механизмы формальных интерфейсов относятся к другой задаче.`}),(0,x.jsx)(`p`,{children:`Одинаковое имя тоже не исчерпывает договор. Если потребитель ожидает строку, а новый вариант меняет файл и возвращает None, вызов синтаксически возможен, но результат не подходит следующему шагу. Мы сравниваем наблюдаемое поведение целиком: какие данные передаются, какое действие выполняется и что потребитель получает обратно. Это практический критерий для маленькой замены, а не гарантия, что два объекта одинаковы во всех ситуациях.`}),(0,x.jsx)(u,{statement:(0,x.jsxs)(x.Fragment,{children:[`Если два канала поддерживают `,(0,x.jsx)(`code`,{children:`deliver(message)`}),`, один из них обязательно должен наследоваться от другого.`]}),isTrue:!1,explanation:`Композиция требует подходящего действия, а не общего родителя. В нашем примере Reminder использует любой канал с нужным методом.`})]}),(0,x.jsxs)(c,{number:`04`,title:`Отношение «использует» не равно «является»`,children:[(0,x.jsx)(s,{children:`Наследование уместно, когда новый тип действительно является разновидностью базового типа. Композиция описывает другую связь: один объект пользуется возможностью другого. В Planner эти слова помогают не переносить ответственность между моделью, хранением и интерфейсом.`}),(0,x.jsx)(`p`,{children:`Представим книгу на полке. Книга находится на полке и может быть положена на другую, но от этого книга не становится разновидностью мебели для хранения. Так же Task может быть сохранена через компонент хранения, но не становится разновидностью storage. Аналогия показывает только различие двух отношений; в программе решение всё равно сверяем с обязанностями и вызываемым поведением.`}),(0,x.jsx)(`p`,{children:`Вызов метода другого объекта ещё не требует, чтобы вызывающий объект создавал его внутри себя. Передача зависимости снаружи делает выбор заметным и позволяет заменить вариант. Но это решение не бесплатно: теперь потребитель зависит от имени метода и нужного ему поведения. Если альтернативы нет и отдельная ответственность не появляется, дополнительный объект может лишь усложнить путь чтения.`}),(0,x.jsx)(`p`,{children:`Наследование также добавляет связь между типами: новый тип заявляет, что является разновидностью другого и получает его поведение. Переиспользовать одну удобную функцию или связать данные с файлом недостаточно для такого утверждения. Если Task унаследует storage, читатель кода получит неверную картину: задача будет выглядеть частным видом хранилища, хотя её роль другая. Сначала называем отношение словами, затем выбираем механизм, который это отношение действительно выражает.`}),(0,x.jsx)(r,{tone:`info`,children:`Вспомним границу: композиция объясняет сотрудничество уже выбранных объектов. Она сама по себе не требует создавать абстрактный базовый класс, фабрику, контейнер зависимостей или новый сервис.`})]}),(0,x.jsxs)(c,{number:`05`,title:`Распределяем роли Planner без преждевременной реализации`,children:[(0,x.jsx)(s,{children:`Теперь применим критерии к знакомому проекту. Мы уже знаем его части по функциональному пути, но будущие классы сервиса и хранения пока не созданы. Карта ответственности помогает спланировать интеграцию, не выдавая план за готовый код.`}),(0,x.jsx)(`p`,{children:`Task описывает одну задачу: её данные, состояние и локальные изменения. Список задач относится ко всему Planner, поэтому одна Task не становится владельцем набора. Рабочие функции storage загружают и сохраняют записи; один объект Task не должен выбирать путь или самостоятельно открывать JSON. CLI получает команды и показывает результаты. Будущий сервис будет координировать действие над набором через уже подготовленные компоненты. Эти обязанности можно будет связать, но блок 7 не создаёт такие классы заранее.`}),(0,x.jsx)(`p`,{children:`Сведём роли в одну карту ответственности:`}),(0,x.jsx)(t,{rows:[[`Task`,`Описывает одну задачу, её состояние и локальные действия.`],[`storage`,`Восстанавливает и сохраняет записи; рабочий путь пока остаётся функциональным.`],[`будущий сервис`,`Позднее будет координировать операцию над набором задач.`],[`CLI`,`Принимает команды и показывает результаты пользователю.`]]}),(0,x.jsx)(`p`,{children:`Представим четыре отделения мастерской. Карточка заказа хранит состояние одной работы, инструмент выполняет отдельную операцию, складская ведомость отвечает за учёт, а стойка общения принимает запросы. Передача заказа между отделениями не превращает карточку в склад или стойку. Аналогия помогает удержать границы, но реальный Planner состоит из функций и модулей, и нам не нужно назначать каждому отделению класс.`})]}),(0,x.jsxs)(c,{number:`06`,title:`Карта будущих связей не означает готовую реализацию`,children:[(0,x.jsx)(s,{children:`Мы распределили ответственность, но пока не собираем новые классы из этой карты. Название роли помогает объяснить, что компонент будет делать; оно ещё не доказывает, что такой объект существует в рабочем пути.`}),(0,x.jsx)(`p`,{children:`По маршруту блока 6 хранение пока выполняют функции, а Task подготовлена как отдельная модель. Следующий этап включает её в операции и существующий путь JSON. Лишь позднее можно будет рассматривать, полезен ли сервисный объект, который получает компонент хранения и координирует действия над набором. Композиция станет уместна, если один объект действительно вызывает поведение другого, а не потому, что два имени стоят рядом на схеме.`}),(0,x.jsx)(`p`,{children:`Такое разделение защищает нас от двух ошибок. Первая: объявить будущее устройство уже внедрённым. Вторая: добавить класс только потому, что в архитектурной карте есть отдельная роль. Мы сначала сохраняем работающий путь и меняем конкретный компонент в согласованном шаге; архитектура описывает нужную связь, а код подтверждает, что она действительно появилась.`}),(0,x.jsx)(r,{tone:`info`,children:`В этом занятии мы объясняем композицию на отдельном примере, но не создаём PlannerService, storage-класс, контейнер зависимостей или новые команды CLI.`})]}),(0,x.jsxs)(c,{number:`07`,title:`Проверим выбор на спорных решениях`,children:[(0,x.jsx)(s,{children:`Теперь применим те же вопросы к трём предложениям: какую ответственность оно добавляет, какое отношение заявляет и есть ли для этой формы самостоятельная причина?`}),(0,x.jsx)(_,{prompt:`Соединим спорное решение с тем, что в нём не сходится.`,leftTitle:`Предложение`,rightTitle:`Причина сомнения`,pairs:[{left:`Сделать normalize_title отдельным классом`,right:`Для преобразования без своего состояния достаточно функции`},{left:`Унаследовать Task от storage`,right:`Задача сохраняется через storage, но не является хранилищем`},{left:`Хранить все задачи внутри одной Task`,right:`Одна модель описывает одну запись, а не весь набор Planner`}],explanation:`Мы проверили каждый выбор по ответственности: функция не получает лишний объект, Task сохраняет роль одной модели, а обязанности всего набора остаются выше.`}),(0,x.jsx)(`p`,{children:`В спорных решениях часто встречается одна и та же подмена: удобство реализации принимают за правильное отношение. Общая строка данных не делает типы родственниками, а совместный путь не означает, что один компонент должен вобрать обязанности другого. Если назначение класса трудно объяснить одним действием и его состоянием, мы возвращаемся к более простой форме и сравниваем результат.`}),(0,x.jsx)(y,{question:`Объясним своими словами: почему Task не является storage и что остаётся прежним при замене совместимой зависимости?`,hint:`Сначала назовём обязанности одного объекта, затем ожидаемый вызов потребителя.`,answer:(0,x.jsx)(`p`,{children:`Task описывает одну задачу, а storage отвечает за восстановление и сохранение данных. Связь вызова означала бы «использует», не «является». При композиции потребитель продолжает вызывать ожидаемый метод; меняется переданный объект и его результат. В блоке 7 мы не меняем рабочий CLI или JSON.`})})]}),(0,x.jsxs)(c,{number:`08`,title:`Что мы будем делать в практике`,children:[(0,x.jsx)(s,{children:`Короткое исследование перенесёт композицию на отдельный пример, а затем мы применим те же вопросы к Planner. Здесь важен наблюдаемый вызов зависимости и объяснение границ, а не новый слой кода проекта.`}),(0,x.jsx)(m,{variant:`connected`,items:[{title:`Передадим зависимость потребителю`,description:`Проследим, какой метод вызывает объект и какой результат возвращает пример.`},{title:`Подменим совместимый вариант`,description:`Увидим новый результат при прежнем способе вызова со стороны потребителя.`},{title:`Объясним границу связи`,description:`Различим переданную ссылку, отдельный объект и наследование.`},{title:`Разберём роли Planner`,description:`Назовём ответственность Task, хранения, будущего сервиса и CLI без создания этих компонентов.`}]}),(0,x.jsx)(`p`,{children:`Исследование опирается на уже подготовленную Task и не меняет её, каталог практики или действующий путь сохранения. Мы подтвердим понимание по замене зависимости и аргументированному разбору трёх спорных решений, а затем передадим в следующее занятие модель с ясными границами. Интеграция Task в операции и JSON относится к следующему шагу маршрута.`})]})]})}export{S as Lesson35};